// Case study tabs. The sample panel is generated by the same logic the Lab runs.
import { DEFAULT_SETTINGS, RECORDS, STAGES } from '../data/lab.js';
import { DOMAINS, LEVELS, runAll } from './pipeline-logic.js';
import { initTabs } from './tabs.js';
import { $, barsHtml, esc } from './util.js';

export function initCase() {
  const tabs = $('#case-tabs');
  if (!tabs) return;
  initTabs(tabs);

  $('#class-domains').innerHTML = DOMAINS.map((d) => `<li>${esc(d.label)}</li>`).join('');
  $('#class-levels').innerHTML = Object.values(LEVELS).map((l) => `<li>${esc(l.label)}</li>`).join('');

  $('#stages-table tbody').innerHTML = STAGES.map((s) => `<tr>
    <td>${esc(s.title)}</td><td>${esc(s.blurb)}</td><td>${esc(s.input)}</td><td>${esc(s.output)}</td></tr>`).join('');

  const { state } = runAll(JSON.parse(JSON.stringify(DEFAULT_SETTINGS)));
  const rec = state.recs.find((r) => r.id === 'r3');
  const raw = RECORDS.find((r) => r.id === 'r3');
  $('#sample-in').textContent = JSON.stringify(raw, null, 2);
  $('#sample-out').textContent = JSON.stringify({
    ...rec.norm,
    domain: rec.domain.label,
    domainEvidence: rec.domainEvidence,
    experienceLevel: LEVELS[rec.level].label,
    experienceEvidence: rec.levelEvidence,
    score: rec.score.total,
  }, null, 2);
  $('#sample-score').innerHTML = barsHtml(rec.score);
  $('#sample-decision').textContent = rec.reason;
  $('#sample-msg').textContent = state.messages.find((m) => m.id === 'r3').text;
}
